29	/** Ungrouped totals per card or action, accumulated in a single pass over conversations. */
30	export function totalsRows(source: LoadedStatsSource, controls: StatsControls): StatsChartRow[] {
31	    const cardsById = new Map(source.cards.map((card) => [card.internalId, card]));
32	    const totals = new Map<string, TotalEntry>();
33	    for (const conversation of source.stats.conversations.filter((fact) => isCountedConversation(fact, controls))) {
34	        const identity = controls.totalsGrouping === 'card' ? conversation.cardInternalId : conversation.actionId;
35	        if (!identity) continue;
36	        const display = controls.totalsGrouping === 'card'
37	            ? cardDisplay(identity, conversation.cardPath, cardsById)
38	            : { label: actionLabel(identity, conversation.actionLabel), tooltip: actionLabel(identity, conversation.actionLabel) };
39	        const value = controls.totalsMetric === 'duration' ? conversation.elapsedMs : conversation.totalTokens;
40	        if (value === null) continue;
41	        const current = totals.get(identity);
42	        totals.set(identity, { label: display.label, tooltip: display.tooltip, value: (current?.value ?? 0) + value });
43	    }
44	    const unit: StatsUnit = controls.totalsMetric === 'duration' ? 'milliseconds' : 'tokens';
45	
46	    return [...totals.entries()]
47	        .map(([identity, { label, tooltip, value }]) => ({
48	            actionId: controls.totalsGrouping === 'action' ? identity : null,
49	            actionType: null,
50	            accessibleLabel: `${tooltip}: ${value} ${unit}`,
51	            agent: null,
52	            available: true,
53	            chartRole: 'primary',
54	            displayLabel: label,
55	            grouping: controls.totalsGrouping,
56	            identity,
57	            denominator: null,
58	            limitId: null,
59	            metric: controls.totalsMetric,
60	            numerator: null,
61	            provider: null,
62	            sampleCount: null,
63	            seriesIdentity: null,
64	            seriesLabel: null,
65	            stackIdentity: null,
66	            stackLabel: null,
67	            statusCounts: null,
68	            tooltip: `${tooltip}: ${value} ${unit}`,
69	            unit,
70	            utcBucketEnd: null,
71	            utcBucketStart: null,
72	            value,
73	            windowId: null,
74	        } satisfies StatsChartRow))
75	        .sort((left, right) => right.value - left.value || left.displayLabel.localeCompare(right.displayLabel));
76	}
